//! The build half of the runtime route: four modules and two generated files.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the native library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time, and
//! linking the archive as well would make the linker demand them before `load`
//! ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core, supplied by the driver.
//!             Pure Zig; imported by the facade in both configurations, because
//!             `LoadSource` and `LoadError` are this SDK's public types and must
//!             be the same types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding, the provider's required symbol set, and
//!             the one load-time check.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             patched translation as `c_native`.
//!   native    the generator's second file: the same translation with the
//!             `__root` prologue Aro writes replaced by an import of the
//!             dispatch as `c_routed`, so a declaration nested inside a
//!             translated type - the per-width aliases - names the routed
//!             wrapper rather than the raw extern. It imports the dispatch and
//!             nothing else.
//!   sync.c    compiled into the dispatch with `-DRT_SYNC_PREFIX=pcre2_rt`, so
//!             its symbols cannot collide with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled C archive into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph should
//! reference the library, or the linker resolves the symbols statically and the
//! runtime route silently becomes a linked one.

const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is the
/// whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "pcre2_rt";

/// `extern` declarations that the C library provides and that must therefore
/// stay direct.
///
/// ## Why this list is as long as it is
///
/// `src/pcre2.h.generic:87-89` includes `<limits.h>`, `<stdlib.h>` and
/// `<inttypes.h>`, and every function those three declare is an `extern`
/// declaration in this build's translation, exactly like `pcre2_match_8` is.
/// The generator cannot tell the two apart: it sees one list of
/// `pub extern` declarations and routes everything it is not told to leave
/// alone.
///
/// ## How the list was derived
///
/// Not by reading headers and not from a list of what a C library "usually"
/// declares: by running the pinned compiler's own `zig translate-c` over this
/// package's aggregate translation unit, `translate.h`, once for every
/// published configuration, and keeping every `pub extern fn|var|const` name
/// that is not PCRE2's own namespace. "Every published configuration" is the
/// published 53-platform Zig 0.16.0 Tier 1/2 table plus this package's six
/// `check` targets (`build.zig:393-400`), at each of the three code-unit
/// widths `-Dcode-unit-width` accepts and each of the two linkages
/// `-Dlinkage` accepts: 58 targets times three widths times two linkages, and
/// all 348 of them translate. Each is read through the front end
/// `aggregateRoute` gives it -- Aro directly on a GNU libc target, and
/// `zig cc -E -dD -fno-blocks` in front of it everywhere else, because Aro's
/// preprocessor cannot read those targets' C library. The list below is the
/// union of their extern names minus the 241 that `pcre2.h` and
/// `pcre2posix.h` declare, so it is a superset of what the generator can be
/// asked about for any of them.
///
/// The headers the aggregate actually reaches are the three above and
/// whatever each of them includes, and that set is not the same on every
/// target. On a glibc target it is `<limits.h>`, `<stdlib.h>`, `<inttypes.h>`
/// and the `<stdint.h>`, `<alloca.h>`, `<endian.h>`, `<sys/select.h>` and
/// `<features.h>` they drag in; on Darwin it is the `_stdlib.h`,
/// `malloc/_malloc.h`, `malloc/_malloc_type.h`, `sys/resource.h`,
/// `sys/wait.h`, `sys/signal.h`, `sys/_endian.h`, `alloca.h`, `_abort.h` and
/// `libkern/_OSByteOrder.h` that `<stdlib.h>` and `<inttypes.h>` reach; on a
/// mingw target it is `<limits.h>`, `<stdlib.h>`, `<inttypes.h>`,
/// `<stdint.h>` and the `crtdefs.h`, `corecrt.h`, `corecrt_wstdlib.h`,
/// `sec_api/stdlib_s.h` and `<malloc.h>` `<stdlib.h>` pulls in; on NetBSD it
/// is `<limits.h>`, `<stdlib.h>` and `<inttypes.h>` plus
/// `sys/inttypes.h`, `sys/bswap.h` and the machine byte-order headers; on
/// OpenBSD it is those three plus `sys/stdint.h` and `sys/endian.h`; on
/// FreeBSD it is those three plus `sys/stdint.h` and the machine
/// `_inttypes.h`; and on WASI it is `wasm-wasi-musl/stdlib.h` and
/// `wasm-wasi-musl/inttypes.h`. There is **no `<string.h>`** in that closure
/// on any target and **no `<wchar.h>`** on any of them either: an earlier
/// revision of this comment claimed a `<string.h>` closure the aggregate does
/// not have, and it was wrong. The `<string.h>` and `<wchar.h>` names that
/// remain listed are kept because this file is target-independent and a name
/// no configuration declares matches nothing, which is harmless; they are not
/// part of the measured closure.
///
/// Their union is listed, not any one libc's, because this file is
/// target-independent and a name a given target's headers do not declare
/// simply matches nothing, which is harmless. A C library name left out of
/// this list would be routed and its table field would never be filled;
/// nothing on the reachable path calls one, but the honest fix is a name here.
///
/// No PCRE2 name appears in this list, and none can: a PCRE2 entry point
/// routed as direct would be the one mistake this file cannot make quietly.
///
/// ### The fortified and alias declarations a C library adds in optimized
/// translations
///
/// The union above was measured over the aggregate as `translate-c` sees it,
/// but `translate-c` reads the target's headers with the *build's* configuration,
/// and in an optimized build that turns `_FORTIFY_SOURCE` on. glibc's
/// `_FORTIFY_SOURCE` block declares a second family of externs that the
/// unfortified pass never sees: a `__*_chk` implementation per fortified
/// function, a `__*_alias` redirect back onto the plain function, and a
/// `__*_chk_warn` sibling. They are declared by the C library and exported by
/// it; `libpcre2-8` exports none of them. That is not an argument, it is what
/// the cached dispatch for the failing configuration shows: the ReleaseSafe
/// table routed seventeen such names and every other configuration's table
/// routed none, which is exactly the shape of a load that passes under
/// `-Doptimize=Debug` and fails with `MissingSymbol` under `-Doptimize=ReleaseSafe`.
///
/// All seventeen are listed, each with the pinned header that declares it:
///
///   * `__fdelt_chk` and `__fdelt_warn`
///     (`lib/libc/include/generic-glibc/bits/select-decl.h:27-28`), reached
///     because `<stdlib.h>` drags in `<sys/select.h>`,
///   * `__realpath_chk`, `__realpath_alias` and `__realpath_chk_warn`
///     (`generic-glibc/bits/stdlib.h:23-34`),
///   * `__ptsname_r_chk`, `__ptsname_r_alias` and `__ptsname_r_chk_warn`
///     (`generic-glibc/bits/stdlib.h:59-69`),
///   * `__wctomb_chk` and `__wctomb_alias`
///     (`generic-glibc/bits/stdlib.h:85-88`),
///   * `__mbstowcs_chk`, `__mbstowcs_nulldst`, `__mbstowcs_alias` and
///     `__mbstowcs_chk_warn` (`generic-glibc/bits/stdlib.h:107-127`),
///   * `__wcstombs_chk`, `__wcstombs_alias` and `__wcstombs_chk_warn`
///     (`generic-glibc/bits/stdlib.h:143-156`).
///
/// None of them begins with `pcre2_`, and none is declared by `pcre2.h` or
/// `pcre2posix.h`, so nothing native-owned is de-routed by adding them. They
/// are listed by name rather than by a `__` prefix rule: a prefix rule would
/// also swallow a legitimate name this file cannot see, and the generator's
/// lookup is by exact name anyway.
const libc_noise =
    \\_Exit,_OSSwapInt32,_OSSwapInt64,___mb_cur_max,___mb_cur_max_func,__assert,__assert_fail,__builtin_alloca,
    \\__byte_swap_u16_variable,__byte_swap_u32_variable,__byte_swap_u64_variable,__ctype_get_mb_cur_max,__debugbreak,
    \\__doserrno,__fastfail,__mb_cur_max,__mingw_aligned_free,__mingw_aligned_malloc,__mingw_aligned_msize,
    \\__mingw_aligned_offset_malloc,__mingw_aligned_offset_realloc,__mingw_aligned_realloc,__mingw_get_crt_info,__mingw_strtod,
    \\__mingw_strtof,__mingw_strtold,__mingw_wcstod,__mingw_wcstof,__mingw_wcstold,__p___argc,__p___argv,__p___wargv,
    \\__p__amblksiz,__p__environ,__p__fmode,__p__osplatform,__p__osver,__p__pgmptr,__p__wenviron,__p__winmajor,__p__winminor,
    \\__p__winver,__p__wpgmptr,__prefetch,__qsort_r_compat,__strtod,__sys_errlist,__sys_nerr,_aligned_free,_aligned_malloc,
    \\_aligned_msize,_aligned_offset_malloc,_aligned_offset_realloc,_aligned_offset_recalloc,_aligned_realloc,
    \\_aligned_recalloc,_atodbl,_atodbl_l,_atof_l,_atoflt,_atoflt_l,_atoi64,_atoi64_l,_atoi_l,_atol_l,_atoldbl,_atoldbl_l,
    \\_beep,_byteswap_uint64,_byteswap_ulong,_byteswap_ushort,_dupenv_s,_ecvt,_ecvt_s,_environ,_errno,_exit,_expand,_fcvt,
    \\_fcvt_s,_fullpath,_gcvt,_gcvt_s,_get_amblksiz,_get_doserrno,_get_errno,_get_fmode,_get_heap_handle,
    \\_get_invalid_parameter_handler,_get_osplatform,_get_osver,_get_pgmptr,_get_purecall_handler,_get_sbh_threshold,
    \\_get_winmajor,_get_winminor,_get_winver,_get_wpgmptr,_heapadd,_heapchk,_heapmin,_heapset,_heapused,_heapwalk,_i64toa,
    \\_i64toa_s,_i64tow,_i64tow_s,_itoa,_itoa_s,_itow,_itow_s,_lrotl,_lrotr,_ltoa,_ltoa_s,_ltow,_ltow_s,_makepath,_makepath_s,
    \\_mb_cur_max_l,_mbctype,_mblen_l,_mbstowcs_l,_mbstowcs_s_l,_mbstrlen,_mbstrlen_l,_mbstrnlen,_mbstrnlen_l,_mbtowc_l,_msize,
    \\_onexit,_pctype,_putenv,_putenv_s,_recalloc,_resetstkoflw,_rotl,_rotl64,_rotr,_rotr64,_searchenv,_searchenv_s,
    \\_set_abort_behavior,_set_amblksiz,_set_doserrno,_set_errno,_set_error_mode,_set_fmode,_set_invalid_parameter_handler,
    \\_set_malloc_crt_max_wait,_set_purecall_handler,_set_sbh_threshold,_seterrormode,_sleep,_splitpath,_splitpath_s,_strtod_l,
